-- Nota no artigo "Responder comentários e transformar em lead": aviso e lead automáticos (04/10/2026). Não repete se rodar de novo.
UPDATE public.ajuda_conteudos
SET como_utilizar = como_utilizar || E'\n\nAtualização de 04/10/2026 — aviso e lead automáticos:\n- Quando alguém comenta algo que indica interesse (por exemplo "valor?", "quanto custa", "aceita troca", "qual o km", "onde fica", "quero"), o sistema cria sozinho um lead com origem "comentário" (Facebook ou Instagram) no CRM e manda um aviso no WhatsApp da responsável, com o nome e o texto do comentário. Não é preciso mais clicar em "Criar lead" para esses casos; para os demais comentários o botão continua valendo.\n- Os comentários que a própria loja faz (respostas) não geram aviso nem lead.\n- O aviso por WhatsApp usa texto livre: a Meta só entrega se a destinatária tiver falado com o número da empresa nas últimas 24 horas. Se o aviso não chegar, o lead aparece do mesmo jeito no CRM.\n- Comentários do Instagram só chegam depois que o app da Meta estiver inscrito no evento "comments" do Instagram (hoje o Instagram só envia mensagens diretas). Enquanto isso não for feito, só os comentários do Facebook aparecem aqui.'
WHERE titulo = 'Responder comentários e transformar em lead (Central de Redes Sociais)'
  AND como_utilizar NOT LIKE '%Atualização de 04/10/2026%';
